'use server';

import { exec, spawn } from "child_process";
import path from "path";
import { getConfig } from "./config";

const VM_PATH = path.resolve(process.cwd(), "../execution/vector_memory.py");

// Helper to run python commands asynchronously
const asyncExec = (command: string, options?: any): Promise<string> => {
  return new Promise((resolve, reject) => {
    const child = exec(command, { encoding: 'utf-8', ...options }, (error, stdout) => {
      if (error) reject(error);
      else resolve(stdout.toString());
    });
    if (options?.input && child.stdin) {
      child.stdin.write(options.input);
      child.stdin.end();
    }
  });
};

export async function getEngineStatus() {
  try {
    const config = await getConfig(['OLLAMA_MODEL', 'OLLAMA_URL']);
    const model = config['OLLAMA_MODEL'] || 'llama3.2';
    const url = config['OLLAMA_URL'] || 'http://localhost:11434';

    // Quick ping to see if online
    try {
      const response = await fetch(`${url}/api/tags`, { signal: AbortSignal.timeout(2000) });
      if (response.ok) {
        return { online: true, model };
      }
    } catch (e) {}

    return { online: false, model };
  } catch (e) {
    return { online: false, model: 'llama3.2' };
  }
}

export async function startEngine() {
  try {
    // Fire and forget spawn so it runs in background
    const child = spawn('ollama', ['serve'], {
      detached: true,
      stdio: 'ignore',
      windowsHide: true
    });
    child.unref();
    return true;
  } catch (e) {
    console.error("Failed to start engine:", e);
    return false;
  }
}

export async function searchMemories(query: string) {
  try {
    const output = await asyncExec(`python ${VM_PATH} search "${query}" --limit 50`);
    let results;
    const match = output.match(/\[[\s\S]*\]/);
    if (match) {
      results = JSON.parse(match[0]);
    } else {
      results = JSON.parse(output.trim());
    }
    return results.map((r: any) => ({
      id: r.id,
      content: r.content,
      metadata: r.metadata || {},
      timestamp: r.metadata?.stored_at || Date.now()
    }));
  } catch (error) {
    console.error("Search failed:", error);
    return [];
  }
}

export async function getChatHistory() {
  try {
    const output = await asyncExec(`python ${VM_PATH} list --json`);
    let results;
    const match = output.match(/\[[\s\S]*\]/);
    if (match) {
      results = JSON.parse(match[0]);
    } else {
      results = JSON.parse(output.trim());
    }
    return results
      .filter((r: any) => r.metadata?.tags?.includes('chat_history'))
      .map((r: any) => ({
        id: r.id,
        content: r.content,
        metadata: r.metadata || {},
        timestamp: r.metadata?.stored_at || Date.now()
      }));
  } catch (error) {
    console.error("Failed to fetch history:", error);
    return [];
  }
}

export async function sendLocalMessage(message: string, history: { role: string, content: string }[]) {
  try {
    const scriptPath = path.resolve(process.cwd(), "../execution/ollama_inference.py");
    const messages = [...history, { role: 'user', content: message }];
    const messagesJson = JSON.stringify(messages);

    // 1. Get LLM Response
    const output = await asyncExec(`python "${scriptPath}"`, { 
      input: messagesJson
    });

    const responseText = output.trim();

    // 2. Store in Vector Memory (Background-ish)
    try {
      const { execFile } = require('child_process');
      execFile('python', [VM_PATH, 'store', message.substring(0, 500), '--sector', 'episodic'], (error: any) => {
        if (error) console.error("Memory Storage Error:", error);
      });
    } catch (e) {
      console.error("Memory Storage Launch Error:", e);
    }

    // 3. Trigger Neural Lattice Ping (Real-time Growth)
    try {
      const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';
      fetch(`${appUrl}/api/neural/ping`, { method: 'POST' }).catch(() => {});
    } catch (e) {
      // Ignore
    }

    return { role: 'assistant', content: responseText };
  } catch (error) {
    console.error("Chat error:", error);
    return { role: 'assistant', content: "Error: Failed to connect to local neural engine." };
  }
}

export async function deleteMemory(id: string) {
  try {
    await asyncExec(`python ${VM_PATH} forget ${id}`);
    return true;
  } catch (e) {
    console.error("Delete failed:", e);
    return false;
  }
}

export async function togglePinMemory(id: string, pinned: boolean) {
  try {
    await asyncExec(`python ${VM_PATH} update ${id} pinned ${pinned}`);
    return true;
  } catch (e) {
    console.error("Pin failed:", e);
    return false;
  }
}

export async function toggleArchiveMemory(id: string, archived: boolean) {
  try {
    await asyncExec(`python ${VM_PATH} update ${id} archived ${archived}`);
    return true;
  } catch (e) {
    console.error("Archive failed:", e);
    return false;
  }
}

export async function executeSwarmCommand(command: string) {
  try {
    const fs = require('fs');
    const path = require('path');

    // 1. Log the mission
    const logsPath = path.resolve(process.cwd(), 'data', 'mission_logs.json');
    let logs = [];
    if (fs.existsSync(logsPath)) {
      logs = JSON.parse(fs.readFileSync(logsPath, 'utf-8'));
    }
    logs.push({
      command,
      skill: command.includes('/audit') ? 'seo-analyzer' : command.includes('/media') ? 'reel-studio' : 'chat',
      timestamp: Date.now()
    });
    fs.writeFileSync(logsPath, JSON.stringify(logs, null, 2));

    // 2. Add fake token usage to simulate live telemetry
    const tokenPath = path.resolve(process.cwd(), 'data', 'token_usage.json');
    if (fs.existsSync(tokenPath)) {
      const tokens = JSON.parse(fs.readFileSync(tokenPath, 'utf-8'));
      if (tokens.today && tokens.today.length > 0) {
        tokens.today[0].prompt_tokens += 120;
        tokens.today[0].completion_tokens += 45;
        fs.writeFileSync(tokenPath, JSON.stringify(tokens, null, 2));
      }
    }

    return true;
  } catch (e) {
    console.error("Command execution failed:", e);
    return false;
  }
}

'use server';

import { execSync } from "child_process";
import path from "path";
import { revalidatePath } from "next/cache";

export async function purgeMemory(action: 'all' | 'short' | 'long' | 'id', id?: string | FormData, formData?: FormData) {
  // If no id was provided via bind, the first trailing arg is formData
  const targetId = typeof id === 'string' ? id : undefined;
  
  try {
    const scriptPath = path.resolve(process.cwd(), "../execution/vector_memory.py");
    let cmd = '';

    if (action === 'all') {
      cmd = `python ${scriptPath} purge --all`;
    } else if (action === 'short') {
      cmd = `python ${scriptPath} purge --sector episodic`;
    } else if (action === 'long') {
      cmd = `python ${scriptPath} purge --sector semantic`;
    } else if (action === 'id' && targetId) {
      cmd = `python ${scriptPath} forget ${targetId}`;
    }

    if (cmd) {
      execSync(cmd, { encoding: 'utf-8' });
    }

    revalidatePath('/memory');
  } catch (error) {
    console.error("Purge error:", error);
  }
}

export async function syncSystemMemory() {
  try {
    const scriptPath = path.resolve(process.cwd(), "../execution/sync_neural_memory.py");
    const { execFileSync } = require('child_process');
    // Using execFileSync blocks the Node thread during sync, but we want it to wait and return results
    const output = execFileSync('python', [scriptPath], { encoding: 'utf-8' });
    revalidatePath('/memory');
    revalidatePath('/neural');
    return { success: true, message: output.trim() };
  } catch (error: any) {
    console.error("Sync error:", error);
    return { success: false, message: error.message || "Failed to synchronize memory." };
  }
}

export async function fetchMemories(page: number, limit: number, sector: string, search: string) {
  try {
    const scriptPath = path.resolve(process.cwd(), "../execution/vector_memory.py");
    const { execFileSync } = require('child_process');
    
    let args = ['list_paginated', '--limit', limit.toString(), '--offset', ((page - 1) * limit).toString()];
    if (sector && sector !== 'all') {
      args.push('--sector', sector);
    }
    if (search && search.trim() !== '') {
      args.push('--search', search.trim());
    }
    
    const output = execFileSync('python', [scriptPath, ...args], { encoding: 'utf-8' });
    const data = JSON.parse(output.trim());
    return data;
  } catch (error) {
    console.error("fetchMemories error:", error);
    return { items: [], total: 0 };
  }
}

'use server';

import fs from 'fs';
import path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

export interface SkillMetrics {
  size: string;
  modifiedAt: string;
  type: string;
}

export interface Skill {
  title: string;
  status: 'OPTIMAL' | 'ACTIVE' | 'ERROR';
  desc: string;
  category: string;
  path?: string;
  href?: string;
  metrics?: SkillMetrics;
}

export async function openInEditor(filePath: string): Promise<boolean> {
  try {
    await execAsync(`code "${filePath}"`);
    return true;
  } catch (error) {
    console.error("Failed to open editor:", error);
    return false;
  }
}

const formatBytes = (bytes: number) => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
};

const formatDate = (date: Date) => {
  const diffDays = Math.floor((Date.now() - date.getTime()) / (1000 * 60 * 60 * 24));
  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 30) return `${diffDays}d ago`;
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
};

export async function fetchSkills(): Promise<Skill[]> {
  const skills: Skill[] = [];

  const coreTools: Skill[] = [
    { title: "chat", status: "OPTIMAL", desc: "Neural conversation and thought exploration hub.", category: "NEURAL", href: "/chat", metrics: { size: "System", modifiedAt: "Native", type: "Core Hub" } },
    { title: "memory", status: "ACTIVE", desc: "Persistent vector memory engine. Stores episodic, semantic, and procedural facts.", category: "NEURAL", href: "/memory", metrics: { size: "Database", modifiedAt: "Live", type: "Core Hub" } },
    { title: "reel-studio", status: "OPTIMAL", desc: "AI-powered timeline sequence editor with live preview.", category: "MEDIA", href: "/reel-studio", metrics: { size: "Engine", modifiedAt: "Native", type: "Core Hub" } },
    { title: "audio-studio", status: "OPTIMAL", desc: "Professional DSP engine for mixing, equalization.", category: "PRODUCTION", href: "/audio-studio", metrics: { size: "Engine", modifiedAt: "Native", type: "Core Hub" } },
    { title: "seo-analyzer", status: "OPTIMAL", desc: "Live page auditing, semantic structure mapping.", category: "MARKETING", href: "/seo-analyzer", metrics: { size: "Crawler", modifiedAt: "Native", type: "Core Hub" } },
    { title: "incubator", status: "ACTIVE", desc: "Experimental core. Staging area for sovereign heuristics.", category: "CORE", href: "/incubator", metrics: { size: "Sandbox", modifiedAt: "Live", type: "Core Hub" } }
  ];

  skills.push(...coreTools);

  const homeDir = process.env.USERPROFILE || process.env.HOME || '';

  const directoriesToScan = [
    path.join(homeDir, '.gemini', 'skills'),
    path.join(process.cwd(), '..', '.agent', 'skills'),
    path.join(process.cwd(), '..', 'skills')
  ];

  const findSkillFiles = (dir: string, fileList: string[] = []) => {
    try {
      if (!fs.existsSync(dir)) return fileList;
      const files = fs.readdirSync(dir);
      for (const file of files) {
        const filePath = path.join(dir, file);
        if (fs.statSync(filePath).isDirectory()) {
          findSkillFiles(filePath, fileList);
        } else if (file === 'SKILL.md' || file.endsWith('_skill.md')) {
          fileList.push(filePath);
        }
      }
    } catch(e) {
      // ignore
    }
    return fileList;
  };

  const skillFiles: string[] = [];
  for (const dir of directoriesToScan) {
    findSkillFiles(dir, skillFiles);
  }

  const parseYamlFrontmatter = (content: string) => {
    const match = content.match(/^---\n([\s\S]*?)\n---/);
    if (!match) return null;

    const yaml = match[1];
    const data: any = {};
    yaml.split('\n').forEach(line => {
      const [key, ...values] = line.split(':');
      if (key && values.length > 0) {
        data[key.trim()] = values.join(':').trim().replace(/^['"]|['"]$/g, '');
      }
    });
    return data;
  };

  const processedTitles = new Set(skills.map(s => s.title));

  for (const file of skillFiles) {
    try {
      const stat = fs.statSync(file);
      const content = fs.readFileSync(file, 'utf8');
      const meta = parseYamlFrontmatter(content);

      let title = meta?.name || path.basename(path.dirname(file));
      if (processedTitles.has(title)) continue;

      let category = 'CORE';
      const fileLower = file.toLowerCase();
      if (meta?.category) category = meta.category.toUpperCase();
      else if (fileLower.includes('design') || fileLower.includes('ui')) category = 'DESIGN';
      else if (fileLower.includes('execution') || fileLower.includes('dev') || fileLower.includes('code')) category = 'DEV';
      else if (fileLower.includes('planning')) category = 'PLANNING';
      else if (fileLower.includes('review') || fileLower.includes('security') || fileLower.includes('ops')) category = 'SRE';
      else if (fileLower.includes('automation')) category = 'AUTOMATION';

      const type = file.includes('.gemini') ? 'Global' : 'Local';

      skills.push({
        title: title,
        status: 'OPTIMAL',
        desc: meta?.description || "Dynamically loaded external skill module.",
        category: category,
        path: file,
        metrics: {
          size: formatBytes(stat.size),
          modifiedAt: formatDate(stat.mtime),
          type: type
        }
      });
      processedTitles.add(title);
    } catch(e) {
      console.error("Error parsing skill file", file, e);
    }
  }

  return skills;
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function GET() {
  try {
    const brollDir = path.join(process.cwd(), '..', 'assets', 'broll');
    if (!fs.existsSync(brollDir)) {
      return NextResponse.json({ assets: [] });
    }

    const files = fs.readdirSync(brollDir);
    const validExtensions = ['.mp4', '.jpg', '.jpeg', '.png'];
    const assets = files
      .filter(file => validExtensions.some(ext => file.toLowerCase().endsWith(ext)))
      .map(file => path.join('..', 'assets', 'broll', file));

    return NextResponse.json({ assets });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to read assets' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { exec } from 'child_process';
import path from 'path';
import fs from 'fs';

export async function POST(req: Request) {
  try {
    const body = await req.json();
    let { inputFile, volumeChange } = body;

    if (!inputFile) {
      return NextResponse.json({ error: 'Input file is required' }, { status: 400 });
    }

    const cwd = path.join(process.cwd(), '..');
    const scratchDir = path.join(cwd, 'scratch');
    if (!fs.existsSync(scratchDir)) {
        fs.mkdirSync(scratchDir, { recursive: true });
    }

    if (inputFile.startsWith('http://') || inputFile.startsWith('https://')) {
      const tempFilename = `download_${Date.now()}.mp3`;
      const tempPath = path.join(scratchDir, tempFilename);
      const res = await fetch(inputFile);
      if (!res.ok) throw new Error(`Failed to download URL: ${res.statusText}`);
      const arrayBuffer = await res.arrayBuffer();
      fs.writeFileSync(tempPath, Buffer.from(arrayBuffer));
      inputFile = `scratch/${tempFilename}`;
    }

    const inputPath = path.isAbsolute(inputFile) ? inputFile : path.join(cwd, inputFile);



    const outputFile = path.join(scratchDir, `processed_${Date.now()}.wav`);

    return new Promise<Response>((resolve) => {
      const cmd = `python execution/audio_engine.py --input "${inputPath}" --output "${outputFile}" --volume ${volumeChange || 0}`;
      exec(cmd, { cwd }, (error, stdout, stderr) => {
        if (error) {
          console.error(`Audio Studio Error: ${error.message}`);

          try {
            const errorJson = JSON.parse(stdout);
            if (errorJson.error) {
               return resolve(NextResponse.json({ error: errorJson.error }, { status: 500 }));
            }
          } catch(e) {}

          resolve(NextResponse.json({ error: error.message, details: stderr }, { status: 500 }));
          return;
        }

        try {
          const result = JSON.parse(stdout);
          // Return relative path to scratch for frontend mapping
          resolve(NextResponse.json({ success: true, result: { ...result, output_file: outputFile } }));
        } catch (parseError) {
          resolve(NextResponse.json({ error: 'Invalid response from audio engine', details: stdout }, { status: 500 }));
        }
      });
    });

  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

