import { NextResponse } from 'next/server';
import { exec } from 'child_process';
import path from 'path';

export async function POST(request: Request) {
  try {
    const { engine, mode, topic, viralTopic, script } = await request.json();

    const cwd = path.join(process.cwd(), '..');

    let scriptGenCmd = 'python execution/script_generator.py';
    let brollTopic = 'technology';

    if (mode === 'script' && script) {
      // User provided exact script - pass it verbatim
      scriptGenCmd += ` --script "${script.replace(/"/g, '\\"')}"`;
      brollTopic = script.substring(0, 50).replace(/"/g, '\\"');
    } else if (mode === 'topic' && topic) {
      // User entered a custom topic - social search + hook wrapping
      scriptGenCmd += ` --topic "${topic.replace(/"/g, '\\"')}"`;
      brollTopic = topic.replace(/"/g, '\\"');
    } else if (mode === 'auto' && viralTopic) {
      // User selected a trending Reddit post title - use it directly, skip social search
      scriptGenCmd += ` --viral-topic "${viralTopic.replace(/"/g, '\\"')}"`;
      brollTopic = viralTopic.split(' ').slice(0, 3).join(' ').replace(/"/g, '\\"');
    }
    // else: auto with no selection - script_generator falls back to scraping itself

    const cmd = `${scriptGenCmd} && python ops/broll_fetcher.py --topic "${brollTopic}" && python execution/video_brain_tts.py --file ./scratch/viral_script.txt --engine ${engine || 'edge'} && python execution/video_brain_semantic.py --timings ./scratch/timings.json --outdir ./scratch`;

    return new Promise<Response>((resolve) => {
      exec(cmd, { cwd }, (error, stdout, stderr) => {
        if (error) {
          console.error(`Voice Gen Error: ${error.message}`);
          resolve(NextResponse.json({ error: error.message, details: stderr }, { status: 500 }));
        } else {
          resolve(NextResponse.json({ success: true, logs: stdout }));
        }
      });
    });
  } catch (error) {
    return NextResponse.json({ error: 'Voice generation failed' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function POST(request: Request) {
  try {
    const { engine, profile } = await request.json();

    const scratchDir = path.join(process.cwd(), '..', 'scratch');
    const historyDir = path.join(scratchDir, 'history');

    if (!fs.existsSync(historyDir)) {
      fs.mkdirSync(historyDir, { recursive: true });
    }

    // Auto-cleanup unpinned old versions (older than 7 days)
    const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
    const now = Date.now();
    const existingDirs = fs.readdirSync(historyDir);

    for (const dirName of existingDirs) {
      const dirPath = path.join(historyDir, dirName);
      const stat = fs.statSync(dirPath);

      if (stat.isDirectory()) {
        const metaPath = path.join(dirPath, 'meta.json');
        let pinned = false;

        if (fs.existsSync(metaPath)) {
          try {
            const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
            pinned = meta.pinned === true;
          } catch (e) {}
        }

        if (!pinned && (now - stat.mtimeMs > SEVEN_DAYS)) {
          // Delete old unpinned folder
          fs.rmSync(dirPath, { recursive: true, force: true });
        }
      }
    }

    // Create new version
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const versionDir = path.join(historyDir, `v_${timestamp}`);
    fs.mkdirSync(versionDir);

    // Copy files
    const filesToCopy = ['semantic_timeline.json', 'timings.json', 'narration.mp3'];
    for (const file of filesToCopy) {
      const src = path.join(scratchDir, file);
      if (fs.existsSync(src)) {
        fs.copyFileSync(src, path.join(versionDir, file));
      }
    }

    // Write meta.json
    const meta = {
      id: `v_${timestamp}`,
      timestamp: new Date().toISOString(),
      engine: engine || 'Unknown',
      profile: profile || 'Unknown',
      pinned: false
    };

    fs.writeFileSync(path.join(versionDir, 'meta.json'), JSON.stringify(meta, null, 2));

    return NextResponse.json({ success: true, version: meta });
  } catch (error) {
    console.error('History save error:', error);
    return NextResponse.json({ error: 'Failed to save history' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { getConfig } from '@/app/actions/config';

const OLLAMA_URL = 'http://127.0.0.1:11434/api/generate';
const TIMEOUT_MS = 60000;

export async function POST(req: Request) {
  const config = await getConfig(['OLLAMA_MODEL_SYNTHESIS']);
  const activeModel = config['OLLAMA_MODEL_SYNTHESIS'] || 'dolphin-llama3';

  try {
    const { title, desc, tags } = await req.json();
    if (!title || !desc) {
      return NextResponse.json({ error: 'Missing title or desc' }, { status: 400 });
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_MS);

    const prompt = `You are a competitive intelligence analyst. Given a software project idea, identify 3 real competing tools or products that solve a similar problem. Return ONLY valid JSON.

Project: "${title}"
Description: "${desc}"
Current Skills/Stack: ${(tags || []).join(', ')}

Return this exact JSON structure:
{
  "competitors": [
    {
      "name": "Tool or Product Name",
      "category": "Open Source | SaaS | Framework | Library",
      "similarity": 85,
      "gap": "One sentence: what our idea does that this tool doesn't",
      "url": "example.com"
    }
  ]
}

Only include 3 competitors. Respond ONLY with valid JSON:`;

    try {
      const res = await fetch(OLLAMA_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: activeModel, prompt, stream: false, format: 'json' }),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
      if (!res.ok) throw new Error('Ollama error');
      const data = await res.json();

      let parsed;
      try {
        parsed = JSON.parse(data.response);
      } catch {
        const match = data.response.match(/\{[\s\S]*\}/);
        if (match) parsed = JSON.parse(match[0]);
        else throw new Error('JSON parse failed');
      }

      return NextResponse.json({ competitors: parsed.competitors || [], ollamaAvailable: true });
    } catch {
      clearTimeout(timeoutId);
      // Heuristic fallback
      return NextResponse.json({
        ollamaAvailable: false,
        competitors: [
          { name: 'GitHub Copilot*', category: 'SaaS', similarity: 60, gap: 'We focus on local-first execution with full context awareness, not cloud-dependent completions.', url: 'github.com/features/copilot' },
