'use client';

import { useState, useEffect, useRef } from 'react';
import { StatusBadge } from './StatusBadge';

export function FloatingJack() {
  const [isOpen, setIsOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'LOGS' | 'CHAT'>('LOGS');
  const [logs, setLogs] = useState<any[]>([]);
  const [messages, setMessages] = useState<{ role: 'JACK' | 'USER'; text: string }[]>([
    { role: 'JACK', text: 'Diagnostics synchronized. All cognitive modules at peak efficiency. Ready for orchestration.' }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [position, setPosition] = useState<{ x: number; y: number } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<HTMLDivElement>(null);
  const offsetRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const enabled = localStorage.getItem('jack-floating-enabled') === 'true';
    setIsOpen(enabled);

    // Set initial position to bottom right if not already moved
    if (!position) {
      setPosition({ x: window.innerWidth - 340, y: window.innerHeight - 420 });
    }

    const fetchLogs = async () => {
      try {
        const res = await fetch('/api/logs');
        const data = await res.json();
        setLogs(data.slice(0, 10)); // Just the latest 10
      } catch (e) {}
    };

    const interval = setInterval(fetchLogs, 3000);
    return () => clearInterval(interval);
  }, []);

  const handleSend = () => {
    if (!inputValue.trim()) return;
    setMessages([...messages, { role: 'USER', text: inputValue }]);
    setInputValue('');
    
    setTimeout(() => {
      setMessages(prev => [...prev, { role: 'JACK', text: 'PROTOCOL_ACK: Transaction recorded in session buffer. Optimizing sub-processes...' }]);
    }, 1000);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    if (!position) return;
    offsetRef.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y
    };
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      setPosition({
        x: e.clientX - offsetRef.current.x,
        y: e.clientY - offsetRef.current.y
      });
    };

    const handleMouseUp = () => setIsDragging(false);

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  if (!isOpen || !position) return null;

  return (
    <div 
      className="fixed z-[9999] shadow-2xl transition-shadow duration-300"
      style={{ 
        left: `${position.x}px`, 
        top: `${position.y}px`,
        cursor: isDragging ? 'grabbing' : 'default'
      }}
    >
      <div className="w-80 glass-card bg-[var(--sidebar-bg)] backdrop-blur-3xl border-[var(--foreground)]/10 overflow-hidden flex flex-col h-[400px]">
        {/* Draggable Header */}
        <div 
          onMouseDown={handleMouseDown}
          className="p-4 bg-white/[0.03] border-b border-[var(--border)] flex items-center justify-between cursor-grab active:cursor-grabbing select-none"
        >
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
            <span className="text-[10px] font-bold text-[var(--foreground)] uppercase tracking-[0.2em]">Live Diagnostics</span>
          </div>
          <div className="flex gap-2">
             <button onClick={() => setActiveTab('LOGS')} className={`text-[9px] font-bold uppercase tracking-widest ${activeTab === 'LOGS' ? 'text-blue-400' : 'text-[var(--foreground)]/20'}`}>Logs</button>
             <button onClick={() => setActiveTab('CHAT')} className={`text-[9px] font-bold uppercase tracking-widest ${activeTab === 'CHAT' ? 'text-blue-400' : 'text-[var(--foreground)]/20'}`}>Chat</button>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {activeTab === 'LOGS' ? (
            <div className="space-y-3">
              {logs.map((log, i) => (
