'use client';

import Link from "next/link";
import { StatusBadge } from "./components/StatusBadge";
import { TokenWidget } from "./components/TokenWidget";
import { motion, Variants } from "framer-motion";
import { Terminal, LayoutGrid, Activity } from "lucide-react";
import { useState, useEffect } from "react";
import dynamic from 'next/dynamic';
import { executeSwarmCommand } from "./actions/chat";
import { useRouter } from "next/navigation";
import { ThemeToggle } from "./components/ThemeToggle";
import { DataMatrix } from "./components/DataMatrix";

const NeuralGraph3D = dynamic(() => import('./components/NeuralGraph3D'), { ssr: false });

const container: Variants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

const item: Variants = {
  hidden: { opacity: 0, y: 10 },
  show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 300, damping: 24 } }
};

export default function Dashboard() {
  const [time, setTime] = useState<string>("00:00:00");
  const [stats, setStats] = useState({ registry: 0, missions: 0, efficiency: 0, uptime: "0", topSkills: [] as string[] });
  const [isLoading, setIsLoading] = useState(true);
  const [commandQuery, setCommandQuery] = useState("");
  const [activeScenario, setActiveScenario] = useState<'command' | 'data'>('command');
  const router = useRouter();

  useEffect(() => {
    setTime(new Date().toLocaleTimeString('en-GB'));
    const interval = setInterval(() => setTime(new Date().toLocaleTimeString('en-GB')), 1000);

    async function fetchStats() {
      try {
        const res = await fetch('/api/stats');
        const data = await res.json();
        setStats(data);
      } catch (e) {
        console.error("Failed to fetch stats", e);
      } finally {
        setIsLoading(false);
      }
    }
    fetchStats();
    const statsInterval = setInterval(fetchStats, 30000);

    return () => {
      clearInterval(interval);
      clearInterval(statsInterval);
    };
  }, []);

  return (
    <>
      {/* Atmospheric Orbs */}
      <div className="atmospheric-orb orb-emerald"></div>
      <div className="atmospheric-orb orb-sapphire"></div>

      <div className="w-full h-full max-w-7xl mx-auto flex flex-col space-y-6 relative z-10 p-4 sm:p-6 lg:p-8">

        {/* Universal Top Bar */}
        <motion.div 
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex justify-between items-center bg-[var(--surface)] border border-[var(--border)] p-2 px-4 rounded-sm shadow-sm"
        >
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setActiveScenario('command')}
              className={`flex items-center gap-2 px-4 py-2 rounded-sm text-[10px] uppercase font-bold tracking-widest font-mono transition-all ${activeScenario === 'command' ? 'bg-[var(--primary)] text-[var(--background)] shadow-[0_0_10px_var(--primary-glow)]' : 'text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--background)]'}`}
            >
              <LayoutGrid size={14} />
              Command Center
            </button>
            <button 
              onClick={() => setActiveScenario('data')}
              className={`flex items-center gap-2 px-4 py-2 rounded-sm text-[10px] uppercase font-bold tracking-widest font-mono transition-all ${activeScenario === 'data' ? 'bg-[var(--primary)] text-[var(--background)] shadow-[0_0_10px_var(--primary-glow)]' : 'text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--background)]'}`}
            >
              <Activity size={14} />
              Data Matrix
            </button>
          </div>

          <div className="flex items-center gap-4">
             <div className="text-right hidden sm:block">
              <p className="text-[10px] font-bold text-[var(--faint)] uppercase tracking-widest mb-0.5 font-mono">Local Time</p>
              <p className="text-sm font-mono text-[var(--primary)] font-bold">{time}</p>
            </div>
            <ThemeToggle />
          </div>
        </motion.div>

        {activeScenario === 'command' ? (
          /* Command Center (Open Design Focus) */
          <>
            <motion.section 
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex justify-between items-end border-b border-[var(--border)] pb-4 mt-2"
            >
              <div>
                <h2 className="text-4xl font-bold tracking-tight mb-2 text-[var(--foreground)] font-mono">Command Center</h2>
                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-bold text-[var(--muted)] uppercase tracking-widest font-mono">Engine Status:</span>
                  <StatusBadge status="OPTIMAL" />
                </div>
              </div>
            </motion.section>

            <motion.div 
              variants={container}
              initial="hidden"
              animate="show"
              className="grid grid-cols-1 md:grid-cols-12 gap-6 flex-1"
            >
              {/* Left Column */}
              <div className="md:col-span-4 flex flex-col gap-6">
                <div className="grid grid-cols-2 gap-4">
                  <StatCard label="Registry" value={isLoading ? "-" : stats.registry.toString()} unit="Skills" trend="optimal" delay={0.1} />
                  <StatCard label="Missions" value={isLoading ? "-" : stats.missions.toString().padStart(2, '0')} unit="Tasks" delay={0.2} />
                  <StatCard label="Token Eff." value={isLoading ? "-" : stats.efficiency.toString()} unit="%" trend="optimal" delay={0.3} />
                  <StatCard label="Uptime" value={isLoading ? "-" : stats.uptime} unit="Hrs" delay={0.4} />
                </div>

                <motion.div variants={item} className="h-48 border border-[var(--border)] bg-[var(--surface)] p-0 rounded-sm overflow-hidden relative group">
                  <TokenWidget />
                </motion.div>

                <motion.div variants={item} className="flex-1 min-h-[160px] border border-[var(--border)] bg-[var(--background)] p-0 flex flex-col relative overflow-hidden group hover:border-[var(--primary)] transition-colors">
                  <Link href="/telemetry" className="absolute inset-0 z-20 cursor-pointer" aria-label="Go to Telemetry Dashboard" />
                  <div className="absolute top-4 left-4 z-10 pointer-events-none">
                    <span className="text-[10px] font-bold text-[var(--primary)] uppercase tracking-widest flex items-center gap-2 font-mono">
                      <span className="w-2 h-2 rounded-full bg-[var(--primary)] animate-pulse shadow-[0_0_8px_var(--primary-glow)]"></span>
                      System Telemetry [Click to Expand]
                    </span>
                  </div>
                  <NeuralGraph3D />
                </motion.div>
              </div>

              {/* Right Column */}
              <div className="md:col-span-8 flex flex-col gap-6">
                <motion.div variants={item} className="flex items-center justify-between border-b border-[var(--border)] pb-2">
                  <div className="flex items-center gap-4">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-[var(--foreground)] font-mono">Deployable Intelligence</h3>
                  </div>
                  <Link href="/skills">
                    <button className="text-[10px] font-bold text-[var(--primary)] uppercase tracking-widest hover:underline font-mono">VIEW ARMORY [Ôåù]</button>
                  </Link>
                </motion.div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <SkillCard title="chat" desc="Neural conversation and thought exploration hub." category="NEURAL" status="OPTIMAL" href="/chat" />
                  <SkillCard title="incubator" desc="Experimental core. Staging area for sovereign heuristics." category="CORE" status="ACTIVE" href="/incubator" />
                  <SkillCard title="reel-studio" desc="AI-powered timeline sequence editor with live preview, voice generation." category="MEDIA" status="OPTIMAL" href="/reel-studio" />

                  {!isLoading && stats.topSkills.filter(s => !['chat', 'incubator', 'reel-studio'].includes(s)).slice(0, 3).map((skill, idx) => (
                    <SkillCard 
                      key={idx} 
                      title={skill} 
                      desc="Frequently deployed intelligence module from recent missions." 
                      category="CORE" 
                      status="OPTIMAL" 
                    />
                  ))}
                </div>
                <motion.div variants={item} className="mt-auto bg-[var(--background)] p-4 relative overflow-hidden group hover:border-[var(--primary)] transition-all border-beam">
                  <div className="absolute top-0 right-0 p-2 opacity-5 pointer-events-none">
                    <span className="text-6xl font-black tracking-tighter text-[var(--foreground)]">CMD</span>
                  </div>
                  <div className="flex items-center gap-4 relative z-10">
                    <Terminal className="w-5 h-5 text-[var(--primary)]" />
                    <div className="flex-1">
                      <input 
                        type="text" 
                        value={commandQuery}
                        onChange={(e) => setCommandQuery(e.target.value)}
                        onKeyDown={async (e) => {
                          if (e.key === 'Enter' && commandQuery.trim()) {
                            await executeSwarmCommand(commandQuery);
                            router.push('/chat');
                          }
                        }}
                        placeholder="Orchestrate the swarm... (e.g. /audit --deep)" 
                        className="bg-transparent border-none outline-none w-full text-sm text-[var(--foreground)] placeholder:text-[var(--muted)] font-mono"
                      />
                    </div>
                    <button 
                      onClick={async () => {
                        if (commandQuery.trim()) {
                          await executeSwarmCommand(commandQuery);
                          router.push('/chat');
                        }
                      }}
                      className="flex items-center gap-2 px-2 py-1 rounded bg-[var(--surface)] border border-[var(--border)] hover:border-[var(--primary)] transition-all cursor-pointer"
                    >
                      <span className="text-[9px] font-bold text-[var(--primary)]">ENTER</span>
                    </button>
                  </div>
                </motion.div>
              </div>
            </motion.div>
          </>
        ) : (
          /* Data Matrix (UI-UX-Pro-Max Focus) */
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex-1"
          >
            <DataMatrix />
          </motion.div>
        )}
      </div>
    </>
  );
}

function StatCard({ label, value, unit, trend, delay = 0 }: { label: string; value: string; unit: string; trend?: string; delay?: number }) {
  return (
    <motion.div variants={item} whileHover={{ scale: 1.02 }} className="border border-[var(--border)] bg-[var(--surface)] p-4 group relative overflow-hidden hover:border-[var(--primary)] transition-all hover:shadow-[0_0_15px_var(--primary-glow)]">
      <div className="flex justify-between items-start mb-2">
        <p className="text-[9px] uppercase tracking-widest font-bold text-[var(--muted)] font-mono">{label}</p>
        {trend && (
          <span className={`text-[9px] font-bold font-mono ${trend === 'optimal' ? 'text-[var(--primary)]' : 'text-[var(--status-blue)]'}`}>
            {trend}
          </span>
        )}
      </div>
      <div className="flex items-baseline gap-1 mt-1">
        <span className="text-2xl font-bold text-[var(--foreground)] font-mono tracking-tight">{value}</span>
        <span className="text-[10px] uppercase text-[var(--muted)] font-bold tracking-widest font-mono">{unit}</span>
      </div>
    </motion.div>
  );
}

function SkillCard({ title, desc, category, status, href = "/skills" }: { title: string; desc: string; category: string; status: any; href?: string }) {
  return (
    <motion.div variants={item} whileHover={{ scale: 1.02 }} className="border border-[var(--border)] bg-[var(--surface)] p-5 flex flex-col h-full group hover:border-[var(--primary)] transition-all cursor-pointer hover:shadow-[0_0_15px_var(--primary-glow)]">
      <div className="flex justify-between items-start mb-3">
        <div className="space-y-2">
          <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-[var(--background)] border border-[var(--border)] text-[var(--primary)] tracking-widest uppercase font-mono">{category}</span>
          <h4 className="font-bold text-sm text-[var(--foreground)] font-mono">{title}</h4>
        </div>
        <div className="w-1.5 h-1.5 rounded-full bg-[var(--primary)] shadow-[0_0_5px_var(--primary-glow)]"></div>
      </div>
      <p className="text-xs text-[var(--muted)] leading-relaxed mb-4 flex-1">{desc}</p>
      <Link href={href} className="mt-auto">
        <button className="w-full py-2 bg-[var(--background)] border border-[var(--border)] text-[10px] font-bold uppercase tracking-widest hover:border-[var(--primary)] hover:text-[var(--primary)] transition-all text-[var(--foreground)] font-mono shiny-button">
          INIT
        </button>
      </Link>
    </motion.div>
  );
}

"use client";

import { useEffect, useState, useRef } from 'react';
import { Play, Pause, Square, Wand2, Upload, FileAudio, Video, Search, Type, Image as ImageIcon, Download, Settings, Trash2, Edit3, Flame, PenTool } from 'lucide-react';

interface Segment {
  text: string;
  start: number;
  end: number;
  clip_path: string;
}

interface Timeline {
  segments: Segment[];
}

export default function Studio() {
  const [timeline, setTimeline] = useState<Timeline | null>(null);
  const [selectedSegmentIdx, setSelectedSegmentIdx] = useState<number | null>(null);
  const [assets, setAssets] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshKey, setRefreshKey] = useState(() => Date.now());
  
  // Render State
  const [renderProfile, setRenderProfile] = useState('FastViral');
  const [voiceEngine, setVoiceEngine] = useState('edge');
  const [scriptInputType, setScriptInputType] = useState<'auto' | 'topic' | 'script'>('auto');
  const [topicInput, setTopicInput] = useState('');
  const [scriptInput, setScriptInput] = useState('');
  const [isGeneratingVoice, setIsGeneratingVoice] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  
  // Avatar Settings
  const [enableAvatar, setEnableAvatar] = useState(false);
  const [avatarImagePath, setAvatarImagePath] = useState<string | null>(null);
  const [isUploadingAvatar, setIsUploadingAvatar] = useState(false);
  
  // Viral topic picker
  const [trendingTopics, setTrendingTopics] = useState<{topic: string; traffic: string}[]>([]);
  const [selectedViralTopic, setSelectedViralTopic] = useState<string | null>(null);
  const [isFetchingTrends, setIsFetchingTrends] = useState(false);
  
  // Media Editor State
  const [editingAsset, setEditingAsset] = useState<string | null>(null);
  const [editRotate, setEditRotate] = useState(0);
  const [editBrightness, setEditBrightness] = useState(1.0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRendering, setIsRendering] = useState(false);
  
  // History State
  const [history, setHistory] = useState<any[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  
  const [renderLogs, setRenderLogs] = useState('');
  
  // Audio Player
  const audioRef = useRef<HTMLAudioElement>(null);

  const fetchHistory = async () => {
    const data = await fetch('/api/history/list').then(res => res.json());
    setHistory(data.versions || []);
  };

  useEffect(() => {
    Promise.all([
      fetch('/api/timeline').then(res => res.json()),
      fetch('/api/assets').then(res => res.json())
    ]).then(([timelineData, assetsData]) => {
      setTimeline(timelineData);
      setAssets(assetsData.assets || []);
      setLoading(false);
      fetchHistory();
    });
  }, []);

  const handleProcessMedia = async () => {
    if (!editingAsset) return;
    setIsProcessing(true);
    setRenderLogs(`Processing ${editingAsset}...\n`);
    
    try {
      const res = await fetch('/api/process-media', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          filePath: editingAsset,
          rotate: editRotate,
          brightness: editBrightness
        }),
      });
      const data = await res.json();
      
      if (data.success) {
        setRenderLogs(prev => prev + `Processing complete.\n`);
        setEditingAsset(null);
        setEditRotate(0);
        setEditBrightness(1.0);
        // Add cache busting param to force video reload
        setAssets([...assets]);
        setRefreshKey(Date.now());
      } else {
        setRenderLogs(prev => prev + `Processing failed: ${data.error}\n`);
      }
    } catch (err) {
      setRenderLogs(prev => prev + 'Failed to process media.\n');
    }
    
    setIsProcessing(false);
  };

  const handleSave = async () => {
    if (!timeline) return;
    await fetch('/api/timeline', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(timeline),
    });
    // Trigger history backup
    await fetch('/api/history/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ engine: voiceEngine, profile: renderProfile }),
    });
    fetchHistory();
    alert('Timeline saved successfully!');
  };

  const handleFetchTrends = async () => {
    setIsFetchingTrends(true);
    setSelectedViralTopic(null);
    try {
      const data = await fetch('/api/trending').then(r => r.json());
      setTrendingTopics(data.topics || []);
    } catch {
      setRenderLogs(prev => prev + 'Failed to fetch trending topics.\n');
    }
    setIsFetchingTrends(false);
  };

  const handleGenerateVoice = async () => {
    setIsGeneratingVoice(true);
    setRenderLogs(`Initiating voice generation using ${voiceEngine}...\n`);
    try {
      const body: Record<string, string> = { engine: voiceEngine, mode: scriptInputType };
      if (scriptInputType === 'auto' && selectedViralTopic) body.viralTopic = selectedViralTopic;
      if (scriptInputType === 'topic' && topicInput) body.topic = topicInput;
      if (scriptInputType === 'script' && scriptInput) body.script = scriptInput;

      const res = await fetch('/api/generate-voice', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      if (data.success) {
        setRenderLogs(prev => prev + 'Voice & Timeline generated successfully!\n' + data.logs);
        // Trigger history backup
        await fetch('/api/history/save', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ engine: voiceEngine, profile: renderProfile }),
        });
        const [timelineData, assetsData] = await Promise.all([
          fetch('/api/timeline').then(res => res.json()),
          fetch('/api/assets').then(res => res.json())
        ]);
        setTimeline(timelineData);
        setAssets(assetsData.assets || []);
        fetchHistory();
        setRefreshKey(Date.now());
      } else {
        setRenderLogs(prev => prev + 'Error:\n' + data.error + '\n' + data.details);
      }
    } catch (err) {
      setRenderLogs(prev => prev + 'Failed to trigger voice generation.\n');
    }
    setIsGeneratingVoice(false);
  };

  const handleRender = async () => {
    setIsRendering(true);
    setRenderLogs('Initiating render...\n');
    try {
      const res = await fetch('/api/render', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
            profile: renderProfile, 
            enableAvatar, 
            avatarImagePath 
        }),
      });
      const data = await res.json();
      if (data.success) {
        setRenderLogs(prev => prev + 'Render Complete!\n' + data.logs);
        alert('Video rendered successfully! Check scratch/final_output.mp4');
      } else {
        setRenderLogs(prev => prev + 'Render Error:\n' + data.error + '\n' + data.details);
      }
    } catch (err) {
      setRenderLogs(prev => prev + 'Failed to trigger render.\n');
    }
    setIsRendering(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    
    setIsUploading(true);
    setRenderLogs(`Uploading ${file.name}...\n`);
    
    const formData = new FormData();
    formData.append('file', file);

    try {
      const res = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      
      if (data.success) {
        setRenderLogs(prev => prev + `Upload complete: ${file.name}\n`);
        // Refresh assets list
        const assetsData = await fetch('/api/assets').then(res => res.json());
        setAssets(assetsData.assets || []);
      } else {
        setRenderLogs(prev => prev + `Upload failed: ${data.error}\n`);
      }
    } catch (err) {
      setRenderLogs(prev => prev + 'Failed to upload file.\n');
    }
    
    setIsUploading(false);
    // Reset file input
    e.target.value = '';
  };

  const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    
    setIsUploadingAvatar(true);
    setRenderLogs(`Uploading Presenter Face: ${file.name}...\n`);
    
    const formData = new FormData();
    formData.append('file', file);
    formData.append('type', 'avatar');

    try {
      const res = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      
      if (data.success) {
        setRenderLogs(prev => prev + `Face upload complete: ${file.name}\n`);
        setAvatarImagePath(data.filePath);
      } else {
        setRenderLogs(prev => prev + `Upload failed: ${data.error}\n`);
      }
    } catch (err) {
      setRenderLogs(prev => prev + 'Failed to upload file.\n');
    }
    
    setIsUploadingAvatar(false);
    e.target.value = '';
  };

  const updateSegmentClip = (clip_path: string) => {
    if (selectedSegmentIdx !== null && timeline) {
      const newTimeline = { ...timeline };
      newTimeline.segments[selectedSegmentIdx].clip_path = clip_path;
      setTimeline(newTimeline);
    }
  };

  const updateSegmentText = (newText: string) => {
    if (selectedSegmentIdx !== null && timeline) {
      const newTimeline = { ...timeline };
      newTimeline.segments[selectedSegmentIdx].text = newText;
      setTimeline(newTimeline);
    }
  };

  const playSegment = (start: number) => {
    if (audioRef.current) {
      audioRef.current.currentTime = start;
      audioRef.current.play();
    }
  };

  const handleVideoHover = (e: React.MouseEvent<HTMLVideoElement>) => {
    e.currentTarget.play().catch(() => {});
  };

  const handleVideoLeave = (e: React.MouseEvent<HTMLVideoElement>) => {
    e.currentTarget.pause();
    e.currentTarget.currentTime = 0;
  };

  const handleRestoreVersion = async (id: string) => {
    const res = await fetch('/api/history/restore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id }),
    });
    if (res.ok) {
      window.location.reload();
    }
  };

  const handlePinVersion = async (id: string) => {
    await fetch('/api/history/pin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id }),
    });
    fetchHistory();
  };

  if (loading) {
    return <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center text-[var(--foreground)] font-mono text-sm">Loading Environment...</div>;
  }

  return (
    <>
      <div className="atmospheric-orb orb-emerald"></div>
      <div className="atmospheric-orb orb-sapphire"></div>
      <div className="min-h-screen bg-transparent text-[var(--foreground)] font-sans tracking-tight relative z-10">
        <div className="max-w-7xl mx-auto px-6 py-10 space-y-10">
        
        {/* Minimal Header */}
        <header className="flex justify-between items-center pb-8 border-b border-[var(--border)]">
          <div>
            <h1 className="text-2xl font-semibold tracking-tighter text-[var(--foreground)]">
              Studio Workspace
            </h1>
            <div className="mt-4 flex items-center gap-4">
              <span className="flex items-center gap-2 text-xs text-[var(--muted)] font-mono">
                <span className="h-1.5 w-1.5 rounded-full bg-green-500"></span> Online
              </span>
              <audio ref={audioRef} controls src={`/api/audio?v=${refreshKey}`} className="h-6 opacity-60 hover:opacity-100 transition-opacity filter invert-[0.9] grayscale" />
            </div>


          </div>
          
          <div className="flex gap-6 items-center relative">
            
            <div className="flex flex-col gap-1.5 border-l border-[var(--border)] pl-6">
              <label className="text-xs text-[var(--muted)] font-medium uppercase">Engine</label>
              <select 
                value={voiceEngine} 
                onChange={e => setVoiceEngine(e.target.value)}
                className="bg-transparent border border-[var(--border)] rounded-md px-3 py-1.5 text-sm text-[var(--foreground)] focus:outline-none focus:border-[var(--primary)] cursor-pointer"
              >
                <option value="edge">Edge TTS</option>
                <option value="piper">Piper (CPU)</option>
                <option value="bark">Bark (GPU)</option>
              </select>
            </div>
            
            <button 
              onClick={handleGenerateVoice}
              disabled={isGeneratingVoice || isRendering}
              className="mt-5 text-sm text-[var(--muted)] hover:text-[var(--foreground)] transition-colors disabled:opacity-50"
            >
              {isGeneratingVoice ? 'Generating...' : 'Regenerate Voice'}
            </button>

            <div className="flex flex-col gap-1.5 border-l border-[var(--border)] pl-6">
              <label className="text-xs text-[var(--muted)] font-medium uppercase">Profile</label>
              <select 
                value={renderProfile} 
                onChange={e => setRenderProfile(e.target.value)}
                className="bg-transparent border border-[var(--border)] rounded-md px-3 py-1.5 text-sm text-[var(--foreground)] focus:outline-none focus:border-[var(--primary)] cursor-pointer"
              >
                <option value="FastViral">FastViral</option>
                <option value="CorporateClean">CorporateClean</option>
              </select>
            </div>
            
            <button 
              onClick={handleSave}
              className="mt-5 text-sm text-[var(--muted)] hover:text-[var(--foreground)] transition-colors"
            >
              Save Timeline
            </button>
            <button 
              onClick={handleRender}
              disabled={isRendering || isGeneratingVoice}
              className="mt-5 px-8 py-2 rounded-md text-sm font-bold disabled:opacity-50 disabled:cursor-not-allowed shiny-button"
            >
              {isRendering ? 'Rendering...' : 'Build Video'}
            </button>
          </div>
        </header>

        {/* Content Generation Control Panel */}
        <section className="bg-[var(--surface)] border border-[var(--border)] rounded-xl p-6 space-y-4 hover:border-[var(--primary)] transition-all">
          <div className="flex items-center justify-between">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Content Generation</h2>
            <div className="flex gap-2">
              {(['auto', 'topic', 'script'] as const).map(type => (
                <button 
                  key={type}
                  onClick={() => { setScriptInputType(type); setSelectedViralTopic(null); setTrendingTopics([]); }}
                  className={`px-6 py-2 text-xs font-bold uppercase tracking-widest rounded transition-colors ${scriptInputType === type ? 'shiny-button active' : 'bg-[var(--background)] text-[var(--muted)] border border-[var(--border)] hover:border-[var(--primary)]'}`}
                >
                  {type === 'auto' ? <span className="flex items-center gap-1"><Flame size={12}/> Viral</span> : type === 'topic' ? <span className="flex items-center gap-1"><Search size={12}/> Topic</span> : <span className="flex items-center gap-1"><PenTool size={12}/> Script</span>}
                </button>
              ))}
            </div>
          </div>

          {/* VIRAL AUTO: fetch + pick a trending topic */}
          {scriptInputType === 'auto' && (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <button
                  onClick={handleFetchTrends}
                  disabled={isFetchingTrends}
                  className="flex items-center gap-2 px-6 py-2 text-xs font-bold bg-[var(--primary)]/10 hover:bg-[var(--primary)]/20 border border-[var(--primary)]/30 text-[var(--primary)] rounded-lg transition-colors disabled:opacity-50"
                >
                  {isFetchingTrends ? (
                    <><div className="w-3 h-3 border border-[var(--primary)] border-t-transparent rounded-full animate-spin" /> Fetching...</>
                  ) : (
                    <>ÔÜí Fetch Today&apos;s Trending Topics</>
                  )}
                </button>
                {selectedViralTopic && (
                  <span className="text-xs text-green-400 font-mono">Ô£ô Ready ÔÇö hit Regenerate Voice</span>
                )}
              </div>
              {trendingTopics.length > 0 && (
                <div className="space-y-2">
                  {trendingTopics.map((t, i) => (
                    <button
                      key={i}
                      onClick={() => setSelectedViralTopic(t.topic)}
                      className={`w-full text-left px-4 py-3 rounded-lg text-xs border transition-all ${
                        selectedViralTopic === t.topic
                          ? 'border-[var(--primary)]/60 bg-[var(--primary)]/10 text-[var(--foreground)]'
                          : 'border-[var(--border)] bg-[var(--background)] hover:border-[var(--primary)] text-[var(--muted)] hover:text-[var(--foreground)]'
                      }`}
                    >
                      <span className="text-[var(--muted)] mr-2 font-mono">#{i+1}</span>
                      {t.topic.replace(/^TIL\s*(that)?\s*/i, '')}
                    </button>
                  ))}
                </div>
              )}
              {trendingTopics.length === 0 && !isFetchingTrends && (
                <p className="text-xs text-[var(--faint)] font-mono">Hit &quot;Fetch&quot; to load today&apos;s top Reddit facts and pick one.</p>
              )}
            </div>
          )}

          {/* TOPIC: custom search term ÔåÆ social scraping */}
          {scriptInputType === 'topic' && (
            <div className="space-y-2">
              <input 
                type="text" 
                value={topicInput}
                onChange={e => setTopicInput(e.target.value)}
                placeholder="Enter a topic (e.g. The history of AI, Space exploration)" 
                className="w-full bg-[var(--background)] border border-[var(--border)] rounded-lg px-4 py-3 text-[var(--foreground)] placeholder:text-[var(--faint)] focus:outline-none focus:border-[var(--primary)] transition-colors font-mono text-sm"
              />
              <p className="text-xs text-[var(--faint)] font-mono">Agent will search Reddit + Twitter/TikTok for the most viral post on this topic and build a hook from it.</p>
            </div>
          )}

          {/* SCRIPT: verbatim */}
          {scriptInputType === 'script' && (
            <div className="space-y-2">
              <textarea 
                value={scriptInput}
                onChange={e => setScriptInput(e.target.value)}
                placeholder="Paste your exact script here ÔÇö read word for word by the AI voice." 
                rows={4}
                className="w-full bg-[var(--background)] border border-[var(--border)] rounded-lg px-4 py-3 text-[var(--foreground)] placeholder:text-[var(--faint)] focus:outline-none focus:border-[var(--primary)] transition-colors font-mono text-sm resize-none"
              />
              <p className="text-xs text-[var(--faint)] font-mono">No scraping. Your exact words go straight into the voice engine.</p>
            </div>
          )}
          
          <div className="pt-4 border-t border-[var(--border)] mt-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <label className="flex items-center gap-2 cursor-pointer">
                <div className={`w-10 h-5 rounded-full p-1 transition-colors ${enableAvatar ? 'bg-[var(--primary)]' : 'bg-[var(--surface)] border border-[var(--border)]'}`}>
                  <div className={`bg-white w-3 h-3 rounded-full transition-transform ${enableAvatar ? 'translate-x-5' : 'translate-x-0'}`}></div>
                </div>
                <span className="text-xs font-semibold text-[var(--foreground)]">Enable Split-Screen Avatar</span>
              </label>
              <input type="checkbox" className="hidden" checked={enableAvatar} onChange={() => setEnableAvatar(!enableAvatar)} />
            </div>
            
            {enableAvatar && (
              <div className="flex items-center gap-3">
                {avatarImagePath && (
                  <span className="text-xs text-green-400 font-mono">Ô£ô Face Ready</span>
                )}
                <label className="cursor-pointer px-6 py-2 text-xs font-bold rounded flex items-center gap-2 shiny-button">
                  {isUploadingAvatar ? 'Uploading...' : 'Upload Presenter Face (PNG/JPG)'}
                  <input type="file" className="hidden" accept="image/jpeg,image/png" onChange={handleAvatarUpload} disabled={isUploadingAvatar} />
                </label>
              </div>
            )}
          </div>
        </section>


        {/* Minimal Terminal Log */}
        {(isRendering || isGeneratingVoice || renderLogs) && (
          <div className="bg-[var(--surface)] border border-[var(--border)] rounded-lg p-4 relative hover:border-[var(--primary)] transition-all">
            <button className="absolute top-4 right-4 text-xs text-[var(--faint)] hover:text-[var(--foreground)] transition-colors" onClick={() => setRenderLogs('')}>Clear</button>
            <h3 className="text-xs text-[var(--muted)] uppercase tracking-widest font-mono mb-3">Build Output</h3>
            <pre className="text-xs text-[var(--foreground)] whitespace-pre-wrap max-h-32 overflow-y-auto font-mono scrollbar-hide">
              {renderLogs || "Waiting for signal..."}
            </pre>
          </div>
        )}

        <main className="grid grid-cols-12 gap-10">
          
          {/* Structured Timeline Editor */}
          <div className="col-span-6 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">
              Sequence Editor
            </h2>
            
            <div className="flex flex-col gap-2 overflow-y-auto h-[60vh] pr-2 scrollbar-thin scrollbar-thumb-[var(--border)]">
              {timeline?.segments.map((seg, idx) => (
                <div 
                  key={idx} 
                  className={`relative p-4 rounded-md cursor-pointer transition-all border ${
                    selectedSegmentIdx === idx 
                      ? 'border-[var(--primary)] bg-[var(--surface)] z-10' 
                      : 'border-[var(--border)] hover:border-[var(--primary)] bg-[var(--background)]'
                  }`}
                  onClick={() => {
                    setSelectedSegmentIdx(idx);
                    playSegment(seg.start);
                  }}
                >
                  <div className="flex items-center gap-4 mb-2">
                    <span className="font-mono text-xs text-[var(--faint)]">
                      {seg.start.toFixed(2)}s &rarr; {seg.end.toFixed(2)}s
                    </span>
                    <span className="text-xs bg-[var(--background)] text-[var(--foreground)] px-2 py-0.5 rounded border border-[var(--border)] truncate max-w-[150px]">
                      {seg.clip_path.split('\\').pop()?.split('/').pop()}
                    </span>
                  </div>
                  
                  {selectedSegmentIdx === idx ? (
                     <textarea 
                       className="w-full bg-[var(--background)] border border-[var(--border)] rounded text-sm text-[var(--foreground)] p-2 mt-1 focus:outline-none focus:border-[var(--primary)] resize-none transition-colors"
                       rows={2}
                       value={seg.text}
                       onChange={(e) => updateSegmentText(e.target.value)}
                       onClick={(e) => e.stopPropagation()}
                     />
                  ) : (
                    <p className="text-sm text-[var(--muted)] group-hover:text-[var(--foreground)] transition-colors">{seg.text}</p>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Clean Video Asset Gallery */}
          <div className="col-span-6 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-[var(--foreground)]">
                Media Library
              </h2>
              
              <div className="flex items-center gap-3">
                {selectedSegmentIdx !== null && (
                  <span className="text-xs text-[var(--muted)] font-mono">Targeting Sequence {selectedSegmentIdx + 1}</span>
                )}
                <label className="cursor-pointer bg-[var(--surface)] hover:bg-[var(--surface)] border border-[var(--border)] text-[var(--foreground)] px-3 py-1 rounded text-xs font-medium transition-colors flex items-center gap-2">
                  {isUploading ? (
                    <span className="flex items-center gap-1"><div className="w-2 h-2 border border-[var(--primary)] border-t-transparent rounded-full animate-spin"/> Uploading...</span>
                  ) : (
                    <>
                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                      Upload Media
                    </>
                  )}
                  <input type="file" className="hidden" accept="video/mp4,image/jpeg,image/png" onChange={handleFileUpload} disabled={isUploading} />
                </label>
              </div>
            </div>
            
            {selectedSegmentIdx !== null ? (
              <div className="h-[60vh] overflow-y-auto scrollbar-thin scrollbar-thumb-[var(--border)] pr-2">
                <div className="grid grid-cols-3 gap-4">
                  {assets.map((asset, i) => {
                    const isSelected = timeline?.segments[selectedSegmentIdx].clip_path === asset;
                    // Encode path for query parameter securely
                    const videoUrl = `/api/video?path=${encodeURIComponent(asset)}`;
                    
                    return (
                      <div 
                        key={i}
                        onClick={() => updateSegmentClip(asset)}
                        className={`group relative aspect-[9/16] rounded-md cursor-pointer overflow-hidden border transition-colors ${
                          isSelected 
                            ? 'border-[var(--primary)] shadow-[0_0_15px_var(--primary)]' 
                            : 'border-[var(--border)] hover:border-[var(--primary)]'
                        }`}
                      >
                        <video
                          src={videoUrl}
                          muted
                          loop
                          playsInline
                          onMouseEnter={handleVideoHover}
                          onMouseLeave={handleVideoLeave}
                          className="absolute inset-0 w-full h-full object-cover bg-[var(--background)]"
                        />
                        
                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent pointer-events-none" />
                        
                        <div className="absolute bottom-0 left-0 right-0 p-2 pointer-events-none">
                          <span className="text-xs font-medium text-[var(--foreground)] truncate block w-full drop-shadow-md">
                            {asset.split('\\').pop()?.split('/').pop()?.replace('.mp4', '')}
                          </span>
                        </div>
                        
                        {isSelected && (
                          <div className="absolute top-2 right-2 bg-[var(--primary)] text-[var(--foreground)] rounded-full w-4 h-4 flex items-center justify-center text-xs font-bold">
                            Ô£ô
                          </div>
                        )}

                        {/* Edit Button overlay */}
                        <div className="absolute top-2 left-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={(e) => {
                              e.stopPropagation();
                              setEditingAsset(asset);
                            }}
                            className="bg-[var(--background)]/60 hover:bg-[var(--background)]/80 backdrop-blur border border-[var(--border)] text-[var(--foreground)] p-1.5 rounded-full"
                          >
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ) : (
              <div className="border border-dashed border-[var(--border)] rounded-lg p-12 text-center flex flex-col items-center justify-center h-[60vh]">
                <p className="text-[var(--faint)] text-sm">Select a sequence to browse media.</p>
              </div>
            )}
          </div>
        </main>

        {/* Full-width History Section */}
        <div className="border border-[var(--border)] rounded-lg overflow-hidden bg-[var(--background)]">
          <button 
            onClick={() => setShowHistory(!showHistory)}
            className="w-full p-4 flex justify-between items-center bg-[var(--surface)] hover:bg-[var(--surface)] transition-colors"
          >
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Version History ({history.length})</h2>
            <span className="text-[var(--faint)]">{showHistory ? 'Ôû▓' : 'Ôû╝'}</span>
          </button>
          
          {showHistory && (
            <div className="p-4 border-t border-[var(--border)]">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 max-h-[40vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-[var(--border)]">
                {history.length === 0 ? (
                  <div className="col-span-full text-center text-xs text-[var(--faint)] py-8">No history found.</div>
                ) : (
                  history.map((v, i) => (
                    <div key={v.id} className="p-4 border border-[var(--border)] bg-[var(--surface)] rounded-md hover:border-[var(--primary)] transition-colors flex flex-col gap-3">
                      <div className="flex justify-between items-center">
                        <span className="text-[11px] font-mono text-[var(--muted)]">{new Date(v.timestamp).toLocaleString()}</span>
                        <span className="text-xs bg-[var(--background)] px-2 py-1 rounded text-[var(--faint)]">{v.engine} | {v.profile}</span>
                      </div>
                      <div className="flex gap-2 mt-2">
                        <button 
                          onClick={() => handleRestoreVersion(v.id)}
                          className="flex-1 text-[11px] py-1.5 bg-[var(--background)] hover:bg-[var(--border)] text-[var(--foreground)] border border-[var(--border)] rounded transition-colors"
                        >
                          Restore
                        </button>
                        <button 
                          onClick={() => handlePinVersion(v.id)}
                          className={`text-[11px] px-3 py-1.5 rounded transition-colors ${v.pinned ? 'bg-[var(--primary)]/20 text-[var(--primary)] border border-[var(--primary)]' : 'bg-transparent border border-[var(--border)] text-[var(--muted)] hover:text-[var(--foreground)] hover:border-[var(--primary)]'}`}
                        >
                          {v.pinned ? 'Pinned ­ƒôî' : 'Pin'}
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Editor Modal */}
      {editingAsset && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[var(--background)]/80 backdrop-blur-sm">
          <div className="bg-[var(--surface)] border border-[var(--border)] rounded-xl p-6 w-[400px] max-w-[90vw] shadow-[0_0_50px_var(--primary)]">
            <div className="flex justify-between items-center mb-5 border-b border-[var(--border)] pb-3">
              <h3 className="text-sm font-semibold text-[var(--foreground)]">Media Editor</h3>
              <button onClick={() => setEditingAsset(null)} className="text-[var(--muted)] hover:text-[var(--foreground)]">Ô£ò</button>
            </div>
            
            <div className="space-y-6">
              <div className="flex justify-center bg-[var(--background)] rounded-lg p-4 h-[200px] items-center border border-[var(--border)] overflow-hidden relative">
                {editingAsset.toLowerCase().endsWith('.mp4') ? (
                  <video 
                    src={`/api/video?path=${encodeURIComponent(editingAsset)}&v=${refreshKey}`} 
                    className="max-h-full object-contain transition-transform"
                    autoPlay
                    loop
                    muted 
                    style={{ transform: `rotate(${editRotate}deg)`, filter: `brightness(${editBrightness})` }}
                  />
                ) : (
                  <img 
                    src={`/api/video?path=${encodeURIComponent(editingAsset)}&v=${refreshKey}`} 
                    className="max-h-full object-contain transition-transform" 
                    style={{ transform: `rotate(${editRotate}deg)`, filter: `brightness(${editBrightness})` }}
                  />
                )}
              </div>
              
              <div className="space-y-4">
                <div className="flex flex-col gap-2">
                  <label className="text-xs text-[var(--faint)] uppercase tracking-wider flex justify-between">
                    Rotation <span className="text-[var(--foreground)]">{editRotate}┬░</span>
                  </label>
                  <div className="flex gap-2">
                    {[0, 90, 180, 270].map(deg => (
                      <button 
                        key={deg}
                        onClick={() => setEditRotate(deg)}
                        className={`flex-1 py-2 rounded text-xs font-bold border transition-colors ${
                          editRotate === deg ? 'shiny-button active' : 'bg-transparent text-[var(--muted)] border-[var(--border)] hover:border-[var(--primary)]'
                        }`}
                      >
                        {deg}┬░
                      </button>
                    ))}
                  </div>
                </div>

                <div className="flex flex-col gap-2">
                  <label className="text-xs text-[var(--faint)] uppercase tracking-wider flex justify-between">
                    Brightness <span className="text-[var(--foreground)]">{editBrightness.toFixed(1)}x</span>
                  </label>
                  <input 
                    type="range" min="0.1" max="2.0" step="0.1" 
                    value={editBrightness} 
                    onChange={e => setEditBrightness(parseFloat(e.target.value))}
                    className="w-full h-1 bg-[var(--border)] rounded-lg appearance-none cursor-pointer"
                  />
                </div>
              </div>
              
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setEditingAsset(null)}
                  className="flex-1 py-2 text-xs font-medium border border-[var(--border)] text-[var(--foreground)] rounded hover:bg-[var(--background)] transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleProcessMedia}
                  disabled={isProcessing}
                  className="flex-1 py-3 text-xs font-bold rounded disabled:opacity-50 shiny-button"
                >
                  {isProcessing ? 'Processing...' : 'Apply & Save'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
    </>
  );
}

"use client";

import { useState } from 'react';
import Link from 'next/link';
import { StatusBadge } from '../components/StatusBadge';

interface SeoResult {
  url: string;
  title: string | null;
  meta_description: string | null;
  h1: string[];
  h2: string[];
  word_count: number;
  images: { total: number; without_alt: number };
  links: { internal: number; external: number };
  schema_types: string[];
  score: number;
}

export default function SeoAnalyzer() {
  const [url, setUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<SeoResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const analyzeUrl = async () => {
    if (!url) return;
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const res = await fetch('/api/seo/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
      });
      const data = await res.json();

      if (data.success) {
        setResult(data.result);
      } else {
        setError(data.error || 'Failed to analyze URL');
      }
    } catch (err: any) {
      setError(err.message || 'An error occurred');
    }
    setLoading(false);
  };

  return (
    <>
      <div className="atmospheric-orb orb-emerald"></div>
      <div className="atmospheric-orb orb-sapphire"></div>
      <div className="min-h-screen bg-transparent text-[var(--foreground)] font-sans tracking-tight relative z-10">
        <div className="max-w-6xl mx-auto px-6 py-10 space-y-10">

        {/* Header */}
        <header className="flex justify-between items-center pb-8 border-b border-[var(--border)]">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <Link href="/">
                <button className="text-[var(--muted)] hover:text-[var(--foreground)] transition-colors">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                  </svg>
                </button>
              </Link>
              <h1 className="text-2xl font-semibold tracking-tighter text-[var(--foreground)]">
                SEO & Marketing Analyzer
              </h1>
            </div>
            <div className="flex items-center gap-3 ml-8">
              <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest">Engine Status:</span>
              <StatusBadge status="OPTIMAL" />
            </div>
          </div>
        </header>

        <section className="bg-[var(--surface)] border border-[var(--border)] p-8 rounded-xl space-y-6 hover:border-[var(--primary)] transition-all">
          <div>
            <label className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-3 block">Target URL</label>
            <div className="flex gap-4">
              <input 
                type="url" 
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="https://example.com" 
                className="flex-1 bg-[var(--background)] border border-[var(--border)] rounded-lg px-4 py-3 text-[var(--foreground)] placeholder:text-[var(--faint)] focus:outline-none focus:border-[var(--primary)] transition-colors"
                onKeyDown={(e) => e.key === 'Enter' && analyzeUrl()}
              />
              <button 
                onClick={analyzeUrl}
                disabled={loading || !url}
                className="px-10 py-4 rounded-lg font-bold text-sm disabled:opacity-50 shiny-button"
              >
                {loading ? 'Analyzing...' : 'Audit Target'}
              </button>
            </div>
            {error && <p className="text-red-400 text-sm mt-3 bg-red-400/10 p-3 rounded border border-red-500/20">{error}</p>}
          </div>
        </section>

        {/* Results Section */}
        {result && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Top Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-[var(--surface)] border border-[var(--border)] p-6 rounded-xl flex flex-col justify-between relative overflow-hidden group hover:border-[var(--primary)] transition-all">
                <div className={`absolute -right-4 -top-4 w-24 h-24 rounded-full blur-3xl opacity-20 ${result.score > 80 ? 'bg-green-500' : result.score > 50 ? 'bg-yellow-500' : 'bg-red-500'}`} />
                <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-2 relative z-10">SEO Score</span>
                <span className={`text-5xl font-black tracking-tighter relative z-10 ${result.score > 80 ? 'text-green-400' : result.score > 50 ? 'text-yellow-400' : 'text-red-400'}`}>
                  {result.score}/100
                </span>
              </div>
              <div className="bg-[var(--surface)] border border-[var(--border)] p-6 rounded-xl flex flex-col justify-between hover:border-[var(--primary)] transition-all">
                <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-2">Word Count</span>
                <span className="text-3xl font-bold tracking-tighter text-[var(--foreground)]">{result.word_count}</span>
              </div>
              <div className="bg-[var(--surface)] border border-[var(--border)] p-6 rounded-xl flex flex-col justify-between hover:border-[var(--primary)] transition-all">
                <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-2">Internal Links</span>
                <span className="text-3xl font-bold tracking-tighter text-[var(--foreground)]">{result.links.internal}</span>
              </div>
              <div className="bg-[var(--surface)] border border-[var(--border)] p-6 rounded-xl flex flex-col justify-between hover:border-[var(--primary)] transition-all">
                <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-2">Images w/o Alt</span>
                <span className={`text-3xl font-bold tracking-tighter ${result.images.without_alt > 0 ? 'text-red-400' : 'text-green-400'}`}>
                  {result.images.without_alt} / {result.images.total}
                </span>
              </div>
            </div>

            {/* Detailed Audit */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-[var(--surface)] border border-[var(--border)] p-8 rounded-xl space-y-6 hover:border-[var(--primary)] transition-all">
                <h3 className="text-sm font-bold text-[var(--muted)] uppercase tracking-widest border-b border-[var(--border)] pb-4">Meta Data</h3>

                <div>
                  <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-1 block">Title Tag</span>
                  {result.title ? (
                    <p className="text-sm text-[var(--foreground)]">{result.title}</p>
                  ) : (
                    <p className="text-sm text-red-400 font-mono">Missing Title Tag</p>
                  )}
                  {result.title && (
                     <p className="text-xs text-[var(--faint)] mt-1">{result.title.length} characters</p>
                  )}
                </div>

                <div>
                  <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-1 block">Meta Description</span>
                  {result.meta_description ? (
                    <p className="text-sm text-[var(--foreground)] leading-relaxed">{result.meta_description}</p>
                  ) : (
                    <p className="text-sm text-red-400 font-mono">Missing Meta Description</p>
                  )}
                  {result.meta_description && (
                     <p className="text-xs text-[var(--faint)] mt-1">{result.meta_description.length} characters</p>
                  )}
                </div>
              </div>

              <div className="bg-[var(--surface)] border border-[var(--border)] p-8 rounded-xl space-y-6 hover:border-[var(--primary)] transition-all">
                <h3 className="text-sm font-bold text-[var(--muted)] uppercase tracking-widest border-b border-[var(--border)] pb-4">Semantic Structure</h3>

                <div>
                  <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-1 block">H1 Tag(s) ({result.h1.length})</span>
                  {result.h1.length === 0 ? (
                    <p className="text-sm text-red-400 font-mono">Missing H1</p>
                  ) : result.h1.length > 1 ? (
                    <div className="space-y-2">
                       <p className="text-xs text-yellow-400 uppercase">Warning: Multiple H1s</p>
                       {result.h1.map((h, i) => <p key={i} className="text-sm text-[var(--foreground)] font-mono bg-[var(--background)] p-2 rounded border border-[var(--border)]">{h}</p>)}
                    </div>
                  ) : (
                    <p className="text-sm text-[var(--foreground)] font-mono bg-[var(--background)] p-2 rounded border border-[var(--border)]">{result.h1[0]}</p>
                  )}
                </div>

                <div>
                  <span className="text-xs font-bold text-[var(--muted)] uppercase tracking-widest mb-1 block">Schema JSON-LD</span>
                  {result.schema_types.length > 0 ? (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {result.schema_types.map((t, i) => (
                        <span key={i} className="text-xs font-bold px-2 py-1 rounded bg-[var(--background)] border border-[var(--border)] text-[var(--foreground)]">
                          {t}
                        </span>
                      ))}
                    </div>
                  ) : (
                    <p className="text-sm text-[var(--muted)] font-mono">No structured data found</p>
                  )}
                </div>
              </div>
            </div>

          </div>
        )}

      </div>
    </div>
    </>
  );
}

